import{_ as a}from"./chunks/4b3cdece3d3d963b4a43.ae_l-8xR.js";import{_ as r,C as o,o as l,c as i,j as e,a as n,E as s,a6 as h}from"./chunks/framework.CnPv4DE1.js";const y=JSON.parse('{"title":"赚钱是一种精神修行(如果你学会这些「不道德」的技能)","description":"","frontmatter":{"title":"赚钱是一种精神修行(如果你学会这些「不道德」的技能)","originalTitle":"Making Money Is Spiritual (If You Learn These Unethical Skills)","date":"2023-11-04","originalUrl":"https://thedankoe.com/letters/making-money-is-spiritual-if-you-learn-these-unethical-skills/","minutes":13,"sourceHash":"884d4b471cebf857e82961eda0b32a3f17e33118e3e13067d17ad476a985f8d8","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/making-money-is-spiritual-if-you-learn-these-unethical-skills/"}]]},"headers":[],"relativePath":"letters/making-money-is-spiritual-if-you-learn-these-unethical-skills.md","filePath":"letters/making-money-is-spiritual-if-you-learn-these-unethical-skills.md"}'),u={name:"letters/making-money-is-spiritual-if-you-learn-these-unethical-skills.md"};function c(m,p,f,d,k,g){const t=o("ArticleMeta");return l(),i("div",null,[p[0]||(p[0]=e("h1",{id:"赚钱是一种精神修行-如果你学会这些「不道德」的技能",tabindex:"-1"},[n("赚钱是一种精神修行(如果你学会这些「不道德」的技能) "),e("a",{class:"header-anchor",href:"#赚钱是一种精神修行-如果你学会这些「不道德」的技能","aria-label":'Permalink to "赚钱是一种精神修行(如果你学会这些「不道德」的技能)"'},"​")],-1)),s(t),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/kVj7Py4Yor4?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>在当今世界，你能做的最糟糕的事情之一，就是陷入「清高穷人」的思维陷阱里。</p><p>我认识的很多聪明人讨厌网络生意、营销和销售，因为他们觉得这些东西「低他们一等」。</p><p>他们把自己锁进了一种他们以为是「更高层次」的视角，这种视角把那些油腔滑调的销售员妖魔化。但事实上，这只是一种幻觉。这种「更高层次」的视角里充满了误解、缺乏共情，以及仇恨。</p><p>这种意识水平，和他们所鄙视的「油腔滑调的销售员」相比，非但不高，甚至可能更低。</p><p>这就像民主党和共和党争论谁的意识形态才对；也像无神论者和有神论者争论。当他们陷入这种狭隘的争论时，就根本没有机会发现事情的整体真相。</p><p>让我们开始拆解一下这个整体真相究竟是什么：</p><p>如果你不去创办一家提供信息、教育和产品，让人类变得更好的企业——那么不道德的企业就会在没有竞争的情况下崛起，让人类变得更糟。</p><p>不道德企业充斥市场的原因，正是因为你并没有你自以为的那么有意识、那么聪明。</p><p>你不去创办一家能提升集体意识的企业，实际上就是在直接助长邪恶。</p><p>你什么都不做，只是妖魔化金钱和作为社会命脈的企业，结果你被分配到的工作，其雇主很可能按照你自己的标准来看恰恰就是不道德的。</p><p>你因为自己那些荒诞的<em>假设</em>，以及被灌输的「赚钱不道德」的观念，而不去创业——可你却在为一家让大众生病、参与在世界各地进行轰炸、并把员工困在机器人般的日常routine里、生怕他们发挥出自己潜力的企业打工。</p><p>人们把新兴的创作者教育型企业批评为「骗局」和「诈骗」，可这些企业解决的恰恰是唯一能真正提升人类基线意识的问题。</p><p>那些在健康、财富、关系和幸福领域销售教育课程、课程产品和辅导服务的人，正在攻击积极行为改变的根源。我在《你脑子里困着10万美元》（<a href="/letters/you-have-100000-of-knowledge-trapped-in-your-brain">You Have $100,000 Trapped In Your Head</a>）一文中讨论过教育的重要性。</p><p>如果人类的整体强度只取决于最弱的那一环，而99%的人都在遭受同样的生存问题的折磨，教育又恰恰是让<em>个体</em>能够解决自身问题的手段（而非仅仅提供暂时缓解），问题正是阻碍个人到集体进化的障碍，而教育系统的关注点却是为了自身利益去把人训练成职场工具——那么，这个由价值创造者们组成的新数字社会，就是摆脱这个困境的一条切实可行的出路。</p><p>回到主要论点……</p><p><em>你什么都不做，就等于让那些比你更没有意识、更不聪明的人，获得比你更多的关注、影响力和金钱。</em></p><p>金钱会产生连锁效应，让他们把自己的信息传播得更远，雇用更多员工（这些员工又会助长上述那些不道德的行为），并在社会上不断累积他们所拥有的关注度。</p><p>想让人们不再关注某件事物，唯一的办法就是给他们一个更有说服力的东西去关注。</p><p>这个问题绝不是「随便开个公司赚钱」那么简单。</p><p>万物都是相互连接的，如果你不成为一个有意识的企业主，去影响你的顾客、员工、读者、经济乃至无穷延伸的一切，你就在不知不觉中让整个宇宙的天平倾向邪恶那一方。</p><p><em>灵性，就是理解自己在整个宇宙中所扮演的角色。</em></p><p><em>灵性不是脱离这个整体、跑到树林里去生活，任由宇宙陷入混乱衰败。</em></p><p><em>当你努力通过投入努力和能量，来推动人类的进步与演化，从而试图逆转熵增时，灵性才可以被感受和体会到。</em></p><blockquote><p>幸福是一种感觉，感觉到力量在增长——感觉到阻力正在被克服。——尼采</p></blockquote><p>如果你恨钱，你不也恨你的人生吗？</p><p>你此刻周围的一切——从你手里的手机，到你开车走的公路，到你坐着的这张桌子，到维系你生命的食物——全都是某家企业的产品，而这家企业正是因为对文明发展做出的贡献才赚了钱。</p><p>你正淹没在一个由源自生存本能的赚钱驱动力所建造出来的世界里。</p><p>我在我的新书《专注的艺术》（The Art of Focus）中，从灵性的视角讨论了金钱、营销和销售的重要性。如果你想要一套关于意义、金钱与精进的实用哲学，<a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">点这里获取</a>。</p><h2 id="金钱的重要性-以及它无法被忽视的存在" tabindex="-1">金钱的重要性，以及它无法被忽视的存在 <a class="header-anchor" href="#金钱的重要性-以及它无法被忽视的存在" aria-label="Permalink to &quot;金钱的重要性，以及它无法被忽视的存在&quot;">​</a></h2><p><em>「赚钱最好的方法，就是教别人如何赚钱。」</em></p><p>我经常看到有人这么说。</p><p>有些人把它当作一种智慧来讲。</p><p>另一些人则把这句话当作一个可以拆解任何商业建议的万能句子，好让自己不用去面对现实。</p><p>有些人认为，当金钱主宰人们的生活时，这句话说的就是一件坏事。金钱正是阻碍他们迈向个人发展下一阶段的那个东西。<em>它几乎主导着一个人的每一个行为，即便是最「灵性」的人也不例外，因为金钱与现代生存深深地纠缠在一起。</em></p><p><strong>你为什么一天工作8个小时、连续工作45年？</strong>因为你需要支付账单，养家糊口。</p><p><strong>你为什么会跑去像僧人一样在树林里生活？</strong>因为你想摆脱对金钱的需求，好去追求个人发展。（认为每个人都该这么做，比让社会自行腐烂更愚蠢。「万物为一」——这话说得挺好，直到你真正需要为这个世界的健康承担责任时，你却选择了直接退场）。</p><p><strong>你为什么去健身房、吃健康食物？</strong>是为了健康，没错，但不止于此。你还想提升自己被感知到的地位，以吸引更好的机会，推进你的事业，赚更多的钱。</p><p>我此刻为什么在敲键盘？是为了帮助你，没错，但任何人的行为背后都不会只有<em>一个</em>原因。写作是我的生意。我每周写文章，是因为我因此获得报酬，此外它还给我的生活带来了大量其他好处。</p><p>你为什么在读这篇文章？是为了获得一个新视角，没错，但这也会打开你的思路，减少你在赚钱这件事上的限制性信念。</p><p>你几乎所做的每一个行为，背后都附带着金钱这个原因。</p><p>金钱与现代生存深深地纠缠在一起。</p><p>如果你看马斯洛需求层次理论，在现代世界里，每一个层级都需要金钱。</p><p>你人生中财务这个领域，跟其他任何领域没什么不同。</p><p>就像电子游戏里的技能树一样。</p><p>你人生中所有的领域，都需要随着时间播下种子，花园才能繁荣生长。</p><p>要获得健康，你需要钱。</p><p>要获得令人满足的关系，你需要解决那个摧毁了99%关系的问题……钱。</p><p>要获得快乐（更准确地说是享受生活，因为「快乐」是一个很飘忽不定的衡量标准），你需要朝着一个有意义的目标不断取得进展。你需要去建造。建造需要资源。资源需要钱。</p><p>当你忽视对金钱的需求时，你就限制了自己在心理、身体、乃至灵性修行上能走多远。</p><p>灵性修行？是的。如果你与物质世界的这条命脉——金钱——关系糟糕，那么你的灵性发展就会受阻。你无法获取那种能让你为人类灵性进化做出贡献的资源。</p><p>一切事物本质上都是在「教别人如何赚钱」、推进他们的事业，无论这个建议是从关系、健康与健身，还是学习一项像数字艺术这样的新技能的角度来包装的。</p><p>说实话，你为什么要花12到24年的人生去上学？当然是为了提升你的赚钱能力。是的，你也学会了如何在社会中运作，但社会的命脈是什么？</p><p>学校教的是什么？仅仅是「怎么赚钱」吗？还是一种你可以培养出来的兴趣，最终能帮你赚到钱？</p><p>回到创作者经济这个话题上……</p><p>你难道没看出来，在这个新经济体里，唯一能赚到钱的方式，就是来自那些<em>创造了</em>这个经济体里那些工作和机会的人吗？</p><p>你不理解某件事物，并不意味着它没有用。</p><p>你难道没看出来，在旧经济体里，唯一能赚到钱的方式，就是来自那些创造出那些工作的机构和体制吗？</p><p>万物都在演化。放下你十年前以为管用的那些东西吧。</p><p>学校教的是过时的、赚钱效率更低的方式，因为随着互联网的出现，效率更高的赚钱方式已经诞生了。这就像拖拉机和其他一切被发明出来之后，更高利润的工作也随之出现一样。</p><p>把一切都视为骗局，你就是在把自己的发展推迟数年，甚至可能推迟你的一生。</p><p>这正是我们身处的演化阶段，而你正在错过即将成为新常态的东西。</p><h2 id="你无法回避学习「不道德」的技能" tabindex="-1">你无法回避学习「不道德」的技能 <a class="header-anchor" href="#你无法回避学习「不道德」的技能" aria-label="Permalink to &quot;你无法回避学习「不道德」的技能&quot;">​</a></h2><p>最成功的人，恰恰是那些研究不道德手段、并以道德的方式加以运用的人。</p><ul><li>销售</li><li>营销</li><li>说服</li><li>催眠术</li><li>影响力</li><li>博弈</li></ul><p>他们的工作、事业以及对宏大目标的追求，正是整合自己阴影面的载体。（除了催眠术之外，我在<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学院</a>里从哲学商业的角度，把这些内容都教给了大家）</p><p>当你放大视角去看那些原理时，会发现它们其实都是同一件事。</p><p>所有这些「不道德」的技能，说到底不过是理解人性、心理学，以及宇宙的种种规律模式——就像叙事(甚至建筑和音乐也是一样)：</p><blockquote><p>音乐是流动的建筑；建筑是凝固的音乐。——歌德</p></blockquote><p>每个人都有阴暗的一面。</p><p>就像地毯丑陋的背面，或一首歌里的低音音符。</p><p>宇宙是创造与毁灭、统一与分裂、诞生与死亡之间的平衡。旧建筑被摧毁，才能建起新的建筑。你过去的自我死去，你理想的自我才能诞生。</p><p>你并非纯粹的善。</p><p>当「善」是相对的、且离开「恶」就无法存在时，纯粹的善是不可能存在的。</p><p>那些试图压抑阴暗面、而不是去整合它的人，会让这种阴暗面以不自觉的方式表现出来。往往，那些声称自己不会操控别人的人，恰恰是最会操控人的，只是他们自己没意识到而已。</p><p>从事销售工作或创办一家营销公司，是整合你阴影面的绝佳方式。你被赋予了一个选择：把这些技能用于善，还是用于恶。你能亲眼看到结果，以及它对你和你的客户造成了怎样的影响。</p><p>灵性大师并不是「全然良善」的，他们只是学会了整合自己的恶，不让自己人生这首歌，被写成一首令人沮丧的曲子。你的故事里会有低谷，但当你把视角拉远来看，它最终会走向何处呢？</p><p>一个很好的思考方式，是把你的技能组合看作一支共同基金。</p><p>如果某一只股票下跌了，这支共同基金整体依然可能是上涨的。</p><p>如果某项技能是「不道德」的，那恰恰可能是解开你的生意，让它变得有利可图、合乎道德、并产生影响力的那把钥匙。</p><h2 id="身为人类-就是要去超越、去扩展、去创造" tabindex="-1">身为人类，就是要去超越、去扩展、去创造 <a class="header-anchor" href="#身为人类-就是要去超越、去扩展、去创造" aria-label="Permalink to &quot;身为人类，就是要去超越、去扩展、去创造&quot;">​</a></h2><p>这个世界正在变得疯狂。</p><p>作为一个物种，我们正借助科技、科学和算力，超越物理形态的束缚。</p><p>我们正通过科技，作为一个物种走向统一——意识的统一。如果没有金钱，这一切可能实现吗？</p><p>大多数人认为社交媒体对人类是净负面的，但我完全不这么认为。</p><p>社交媒体是我们记录集体心智的地方。</p><p>我们分享想法、观点、创意、创作，以及我们的身份。我们正在把自己的心智上传到互联网上。不只是创作者。内容本身就是集体心智。</p><p>社交媒体正在瓦解我们沟通方式的边界。</p><p>就好像人们在排队等着进入自己的屏幕。他们整天盯着屏幕。仿佛有一种原始的冲动，想要与其他所有心智融为一体。</p><p>反正你的整个身份已经在屏幕上了，但屏幕本身依然是一层屏障。</p><p>想象一个世界，你可以把一个想法作为信号直接传给另一个人。想象一个世界，你不需要阅读，我的通讯就直接输入到你的心智中。想象一个世界，你在看我的视频时，我就在你身边。</p><p>如果你还没看过 Lex Fridman 与马克·扎克伯格（Mark Zuckerberg）的那场播客（<a href="https://youtu.be/MVYrJJNdrEg" target="_blank" rel="noreferrer">元宇宙中的第一次采访</a>），那个未来其实并不遥远。他们在虚拟现实中做播客，虚拟形象逼真到令人震撼。简直令人瞠目结舌。</p><p>我最近把 <a href="https://theartoffocusbox.com/" target="_blank" rel="noreferrer">The Art Of Focus</a> 活动从线下改成了线上——对此有一种反对意见，认为线下会更有价值，能量不一样。</p><p>我相信现在确实如此，但未来呢？如果虚拟活动能够变得<strong>跟现实一样真实</strong>，而信息流动是即时的，体验也完全超出我们现在能想象的范畴呢？</p><p>再问一个问题：</p><p>整个世界的知识都在你的指尖之下。这让你有什么感觉？</p><p>你有能力去学习、去拓展自我意识、去创办一个为世界提供价值的企业。</p><p>在一项针对孩子们“长大想成为什么”的调查中，得票最高的选项是“YouTuber（YouTube博主）”。</p><p>大多数人认为这既荒谬又不切实际，但我认为这恰恰是自然的、也几乎是未来唯一的选项。也许不是具体成为一个“YouTuber”，而是成为像宇宙本身那样的创作者。你本就是一个用心智进行创造的存在。</p><p>大多数人把渴望影响力和关注度贴上“虚荣”的标签，但很少有人意识到，动机根本无法归结为单一的“为什么”。总有更深层、无意识的东西在推动我们行动和决策。</p><p>在我们的关切、渴望和欲望背后，往往存在着多重“为什么”。</p><p>随着你不断拓展并超越到新的心智层级，你行动背后的动机也会变得越来越全面。</p><p><img src="'+a+'" alt=""></p><p>你的心智层级决定了你的价值观。</p><p>你并不是自己选择去坐着思考金钱、社交媒体和技能获取的。</p><p>你是基于自身心理结构做出的自动化决定。</p><p>对很多人来说，他们被灌输了某种听起来“不错”的意识形态、信念、体系和商业模式，然后开始把自己的信念当作最好、也是唯一正确的东西来捍卫。</p><p>当你放大视角，勇于探索未知，并通过解决问题不断提升自己的心智层级时，你就能看清金钱的本质：一张纸，却能极大地造福自己和他人。</p><h2 id="关于你为何不成功的简要总结" tabindex="-1">关于你为何不成功的简要总结 <a class="header-anchor" href="#关于你为何不成功的简要总结" aria-label="Permalink to &quot;关于你为何不成功的简要总结&quot;">​</a></h2><p>你不成功，是因为你说自己想帮助别人，却不愿去学习那些真正能帮助别人的技能。</p><p>你不成功，是因为你太过专注于“艺术性”，然后当市场看不到你所提供的价值时（因为你没能通过营销和销售把它表达清楚），你就去怪市场。</p><p>你不成功，是因为你只“专注于打磨自己的手艺”，而不是把成果展示给潜在客户。你的网站、设计、文章和其他项目，在别人看到之前都不算数。你在拖延获得反馈的时间。没有反馈，你无法让它变得有价值。你的第一版作品不会有价值。</p><p>你不成功，是因为你对“商业”的理解不完整。商业是你参与人类进步的方式——通过创造一款能提升集体意识的产品。</p><p>你不成功，是因为你把这些话当成了人身攻击，把自己的潜力封闭起来，任由自己的固有观念操控你。</p><p>你不成功，是因为你没有创造出市场愿意为之付费的有价值的东西。人们想要的不是你的自我（ego）想要的东西，而是大自然母亲想要的东西——你算什么，凭什么以为自己知道那应该是什么？</p><p>你不成功，是因为你在自己信奉的那些自以为高尚的信念里寻求安慰。你把自己锁进一个阻碍个人成长的思维框架里。你开始的是应付，而不是创造。</p><blockquote><p>自我发展是通向创业的入门毒品，因为你会意识到，提升他人是提升自己的更高层级。</p></blockquote><p>要想成功，有一条黄金法则：</p><p>为他人提供价值。</p><p>这意味着两件事：</p><ol><li><strong>你必须培育自己的价值。</strong> 你必须拓展心智、识别问题、习得解决问题的技能，并在现实中取得切实的进展。（你不能只是整天坐着学理论，你必须去实践。）</li><li><strong>你必须分发你的价值。</strong> 你需要一个载体——也就是一家企业——去分发市场<strong>想要</strong>购买的产品或服务。如果他们不想要，那它就没有你想象中那么有价值。</li></ol><p>换句话说，你既需要自我发展，<strong>也</strong>需要“他人发展”。</p><p>个人成长和事业成长。</p><p>商业是你规模化地为他人提供价值的方式。</p><p>在这个现代世界里，你要如何培育并分发价值？</p><p>社交媒体。虚拟现实。</p><p>社交媒体是你的公立学校，是你的公开简历，也是你的公开作品集。</p><p>它汇聚了美好人生的神圣三位一体：学习、构建、销售。</p><p>你通过学习新知识来培育自己的价值。</p><p>你通过打造新项目来巩固自己的价值。</p><p>你通过销售这些项目来分发自己的价值。</p><p>这三者共同作用，会带来更有价值的技能和心态。</p><p>好了，这篇信主要讲的是心态。目的是帮你打破限制性信念，为你提供一种能通向更好未来的世界观。</p><p>如果你想看之前关于技能层面的信件，我建议从我的<a href="https://thedankoe.com/blog/category/entrepreneurship/" target="_blank" rel="noreferrer">创业系列文章</a>开始。滑到页面最下方，从那里读起。</p><p>回头聊，</p><p>丹·科伊（Dan Koe）</p><p>附言：The Art Of Focus 纪念礼盒的价格将在不到一周内上涨（在那之前你不会再收到下一期 Koe Letter）。</p><p>它现在有了新的价格方案，以及更棒的线上活动。</p><p><a href="https://theartoffocusbox.com/" target="_blank" rel="noreferrer">点击这里查看。</a></p><hr><p><a href="/en/letters/making-money-is-spiritual-if-you-learn-these-unethical-skills">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',141))])}const T=r(u,[["render",c]]);export{y as __pageData,T as default};
